#include <bits/stdc++.h>

using namespace std;

const long long inf = 1e18;

struct DSU {
    int n;
    vector<int> p, siz;
    int comp;

    DSU(int N) {
        n = N - 1;
        comp = 0;
        p = vector<int>(n + 1);
        siz = vector<int>(n + 1);
    };

    void create(int x) {
        p[x] = x;
        siz[x] = 1;
        comp++;
    }

    void init() {
        comp = 0;
        for(int v = 1; v <= n; v++) create(v);
    }

    int get(int x) {
        return p[x] = (p[x] == x? x : get(p[x]));
    }

    bool unite(int x, int y) {
        x = get(x), y = get(y);
        if(x == y) return 0;
        if(siz[x] < siz[y]) swap(x, y);
        comp--;
        siz[x] += siz[y];
        p[y] = x;
        return 1;
    }
};

int get_cycles(vector<int> p) {
    int n = p.size();

    vector<int> used(n);
    int cnt = 0;
    for(int i = 0; i < n; i++) {
        if(used[i]) continue;

        int j = i;
        while(!used[j]) {
            used[j] = 1;
            j = p[j];
        }

        cnt++;
    }

    return cnt;
}

long long solve_zero(vector<array<int, 3>> a) {
    int n = (int) a.size();
    int N = n + 1;
    vector<vector<array<int, 3>>> g(N + 1);
    for(int i = 0; i < n; i++) {
        auto [u, v, w] = a[i];
        g[u].push_back({v, w, i});
        g[v].push_back({u, w, i});
    }
    vector<pair<int, int>> parent(N + 1);
    vector<int> used(N + 1), d(N + 1);

    int extra_edge = -1;
    function<void(int, int)> dfs = [&](int v, int p) {
        used[v] = 1;
        for(auto [to, w, idx] : g[v]) {
            if(to == p) continue;
            if(used[to]) {
                extra_edge = idx;
                continue;
            }

            parent[to] = {v, idx};
            d[to] = d[v] + 1;
            dfs(to, v);
        }
    };
    dfs(N, 0); dfs(1, 0);

    assert(extra_edge != -1);
    parent[1] = {N, extra_edge};

    int sign = 1;
    vector<int> p(n);
    for(int v = 1; v <= n; v++) {
        auto [u, idx] = parent[v];
        p[idx] = v - 1;
        if(v > u) sign *= -1;
    }
    int cnt_cycles = get_cycles(p);
    if((n - cnt_cycles) & 1) sign = -sign;

    long long ans = inf;
    int best_idx = extra_edge;
    if(sign == 1) ans = min(ans, (long long) a[extra_edge][2]);

    int v = a[extra_edge][0];
    int u = a[extra_edge][1];
    if(d[v] < d[u]) swap(u, v);

    int prev = u;
    while(v != u) {
        auto [par, idx] = parent[v];

        // Delete (v, p)
        // Add (v, prev)
        sign *= -1;
        if(v > par) sign *= -1;
        if(v > prev) sign *= -1;
        if(sign == 1) ans = min(ans, (long long) a[idx][2]);

        if(a[idx][2] < a[best_idx][2]) best_idx = idx;

        prev = v;
        v = par;
    }

    long long two_operations = inf;
    for(int i = 0; i < n; i++) {
        if(i != best_idx) two_operations = min(two_operations, (long long) a[i][2]);
    }
    two_operations += a[best_idx][2];
    ans = min(ans, two_operations);

    return ans;
}

long long get(vector<array<int, 3>> a) {
    int n = (int) a.size();

    int N = n + 1;
    for(auto &[l, r, w] : a) r++;

    auto edges = a;
    for(auto &[u, v, w] : edges) {
        swap(u, w);
    }
    sort(edges.rbegin(), edges.rend());

    DSU dsu(N + 1);
    dsu.init();
    long long ans = 0;
    for(auto [w, u, v] : edges) {
        if(!dsu.unite(u, v)) ans += w;
    }

    if(dsu.comp > 1) {
        if(dsu.comp > 2) return ans;
        else {
            int cnt_other = 0, max_other = 0;
            for(int v = 1; v <= N; v++) {
                if(dsu.get(N) != dsu.get(v)) {
                    cnt_other++;
                    max_other = max(max_other, v);
                }
            }

            if(cnt_other < max_other) return ans;
            return solve_zero(a);
        }
    }

    vector<vector<array<int, 3>>> g(N + 1);
    for(int i = 0; i < n; i++) {
        auto [u, v, w] = a[i];
        g[u].push_back({v, w, i});
        g[v].push_back({u, w, i});
    }
    vector<pair<int, int>> parent(N + 1);
    vector<int> sz(N + 1, 1), max_dp(N + 1), weight(N + 1);

    function<void(int, int)> dfs = [&](int v, int p) {
        max_dp[v] = v;

        for(auto [to, w, idx] : g[v]) {
            if(to == p) continue;

            parent[to] = {v, idx};
            weight[to] = w;
            dfs(to, v);
            sz[v] += sz[to];
            max_dp[v] = max(max_dp[v], max_dp[to]);
        }
    };
    dfs(N, 0);

    int sign = 1;
    vector<int> p(n);
    for(int v = 1; v <= n; v++) {
        auto [u, idx] = parent[v];
        p[idx] = v - 1;
        if(v > u) sign *= -1;
    }
    int cnt_cycles = get_cycles(p);
    if((n - cnt_cycles) & 1) sign = -sign;

    ans = inf;
    if(sign == 1) ans = 0;
    else {
        reverse(edges.begin(), edges.end());
        ans = edges[0][0] + edges[1][0];

        for(int v = 1; v < N; v++) {
            if(sz[v] < max_dp[v]) ans = min(ans, (long long) weight[v]);
        }
    }

    return ans;
}

